//! Provider logos (icons/providers): the SVG for a provider
//! id, recoloured to the theme's text colour and handed to QML as a data
//! URL. (The files are single-colour artwork in black.)

// `LOGOS`: (id, SVG text), sorted by id (generated by build.rs).
include!(concat!(env!("OUT_DIR"), "/provider_logos.rs"));

/// Ids that share another's logo.
fn alias(id: &str) -> &str {
    match id {
        "openai-codex" | "codex" | "chatgpt" | "azure-openai" => "openai",
        "claude" => "anthropic",
        "gemini" | "google-gemini-cli" | "google-vertex" | "vertex" => "google",
        "copilot" => "github-copilot",
        "ollama-cloud" => "ollama",
        other => other,
    }
}

/// The logo id for a provider ("openai-codex", "anthropic/…"), if any.
pub fn id_for(provider: &str) -> Option<&'static str> {
    let p = provider.to_lowercase();
    let first = p.split(['/', ':']).next().unwrap_or("");
    let want = alias(first);
    LOGOS.iter().find(|(id, _)| *id == want).map(|(id, _)| *id)
}

/// `data:image/svg+xml;base64,…` of the provider's logo in `color`
/// (`#rrggbb`), or "" when it has none.
pub fn data_url(provider: &str, color: &str) -> String {
    let Some(id) = id_for(provider) else { return String::new() };
    let svg = LOGOS.iter().find(|(i, _)| *i == id).map(|(_, s)| *s).unwrap_or("");
    let color = if color.starts_with('#') && color.len() <= 9 { color } else { "#888888" };
    // Unfilled shapes inherit the root's fill; explicit dark fills follow it.
    let recoloured = svg
        .replacen("<svg ", &format!("<svg fill=\"{color}\" "), 1)
        .replace("fill=\"black\"", &format!("fill=\"{color}\""))
        .replace("fill=\"#000\"", &format!("fill=\"{color}\""))
        .replace("fill=\"#000000\"", &format!("fill=\"{color}\""))
        .replace("fill=\"currentColor\"", &format!("fill=\"{color}\""));
    format!("data:image/svg+xml;base64,{}", base64(recoloured.as_bytes()))
}

fn base64(bytes: &[u8]) -> String {
    const T: &[u8; 64] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/";
    let mut out = String::with_capacity(bytes.len().div_ceil(3) * 4);
    for chunk in bytes.chunks(3) {
        let n = (chunk[0] as u32) << 16 | (*chunk.get(1).unwrap_or(&0) as u32) << 8 | *chunk.get(2).unwrap_or(&0) as u32;
        for i in 0..4 {
            if i <= chunk.len() {
                out.push(T[(n >> (18 - 6 * i) & 63) as usize] as char);
            } else {
                out.push('=');
            }
        }
    }
    out
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn maps_providers_to_logos() {
        assert_eq!(id_for("openai-codex"), Some("openai"));
        assert_eq!(id_for("anthropic/claude-sonnet"), Some("anthropic"));
        assert_eq!(id_for("Gemini"), Some("google"));
        assert_eq!(id_for("llama.cpp"), None);
        assert_eq!(base64(b"Man"), "TWFu");
        assert_eq!(base64(b"Ma"), "TWE=");
        assert_eq!(base64(b"M"), "TQ==");
        let url = data_url("openai-codex", "#e0e0e0");
        assert!(url.starts_with("data:image/svg+xml;base64,"));
        assert_eq!(data_url("llama.cpp", "#fff"), "");
    }
}
